-- «Modo aventura»: the rivals of the adventures, in a bot group the gallery
-- does not show.
--
-- A group gains `isListed` (true for every existing one, so nothing in the
-- gallery changes) and the catalogs' block below is regenerated with the new
-- group and the twelve rivals of «El cuaderno del viajero». They borrow the
-- strength of gallery bots, so none of them is calibrated. Nothing existing is
-- edited: the block upserts by code and slug, as the one before it did. See
-- prisma/schema.prisma (BotGroup) and lib/adventure/.

ALTER TABLE "BotGroup" ADD COLUMN "isListed" BOOLEAN NOT NULL DEFAULT true;

-- BEGIN play catalogs: generated by `npm run bots:sql` (prisma/play-catalog-sql.ts); do not edit by hand

ON CONFLICT ("code") DO UPDATE SET "label" = EXCLUDED."label", "ring" = EXCLUDED."ring", "order" = EXCLUDED."order", "isListed" = EXCLUDED."isListed";

ON CONFLICT ("code") DO UPDATE SET "label" = EXCLUDED."label", "initialSeconds" = EXCLUDED."initialSeconds", "incrementSeconds" = EXCLUDED."incrementSeconds", "order" = EXCLUDED."order", "isActive" = EXCLUDED."isActive";

ON CONFLICT ("code") DO UPDATE SET "label" = EXCLUDED."label", "order" = EXCLUDED."order";

ON CONFLICT ("slug") DO UPDATE SET "name" = EXCLUDED."name", "elo" = EXCLUDED."elo", "bio" = EXCLUDED."bio", "openings" = EXCLUDED."openings", "fideElo" = EXCLUDED."fideElo", "fideTitle" = EXCLUDED."fideTitle", "country" = EXCLUDED."country", "ratingAsOf" = EXCLUDED."ratingAsOf", "order" = EXCLUDED."order", "isActive" = EXCLUDED."isActive";

-- END play catalogs
